import"./chunk-2NFLSA4Y.js";var a={solar:{theory:{concept:"[[The Solar System is the Sun and all the bodies held by its gravity: eight planets with their moons, dwarf planets, asteroids, comets and dust.]] The planets move around it in the same direction, on slightly elongated ellipses that lie almost in one plane. The closer a planet is to the Sun, the faster it moves and the shorter its year: by Kepler's third law T\xB2 = a\xB3, with T in years and a in astronomical units (1 AU \u2248 150 million km). The simulation starts with the planets where they are today."},section:{sun:{title:"The Sun",text:"[[An ordinary star \u2014 a huge ball of hot gas that shines because of nuclear fusion in its core.]] It holds 99.86 % of all the mass of the Solar System, so its gravity keeps everything in orbit."},rocky:{title:"Rocky planets: Mercury, Venus, Earth, Mars",text:"Small planets with a solid surface, close to the Sun. Venus is the hottest \u2014 its thick carbon-dioxide air traps heat (greenhouse effect), even though Mercury is closer to the Sun."},giants:{title:"Giant planets",text:"Jupiter and Saturn are gas giants made mostly of hydrogen and helium; Uranus and Neptune are ice giants. They have no solid surface, many moons and rings \u2014 Saturn's are the brightest."},small:{title:"Small bodies",text:"Between Mars and Jupiter lies the asteroid belt. Beyond Neptune are icy dwarf planets such as Pluto (a planet until 2006) and the starting point of many comets."},scale:{title:"How big is it really?",text:"If the Sun were a football, Earth would be a peppercorn 25 m away and Neptune a pea 750 m away. That is why the planets are drawn much larger than to scale \u2014 otherwise you would see only empty space."},gravity:{title:"Why planets orbit",text:"The Sun's gravity pulls each planet towards it. [[The planet also moves sideways very fast, so instead of falling in it keeps \u201Cmissing\u201D the Sun \u2014 that is an orbit.]]"},kepler:{title:"Kepler's laws",text:"1) Orbits are ellipses with the Sun at one focus. 2) A planet moves faster when it is closer to the Sun. 3) The square of the period is proportional to the cube of the orbit size: T\xB2 = a\xB3 (T in years, a in AU)."}},formula:{au:"Astronomical unit: the average Earth\u2013Sun distance",kepler3:"Kepler's third law (T in Earth years, a in AU)",gravity:"Law of universal gravitation",visViva:"Orbital speed at distance r (vis-viva equation)",keplerEquation:"Kepler's equation for the position on the ellipse"},assumption:{sizes:"The Sun and planets are drawn far larger than to scale so that you can see them.",distances:"In the \u201Ccompressed\u201D view distances from the Sun are squeezed (directions stay correct); choose \u201Ctrue distances\u201D to see the real proportions.",twoBody:"Each planet is pulled only by the Sun; the small pulls of the planets on each other are ignored. Positions are accurate to about a degree for the years 1800\u20132050.",moons:"Moons, dwarf planets and asteroids are not drawn. The numbers of moons are the confirmed counts in 2025; astronomers keep finding new small moons.",averages:"Temperatures are averages; real temperatures change between day and night and with latitude."},param:{focus:"Planet",daysPerSecond:"Speed of time (days per second)",distanceScale:"Distances"},hint:{focus:"Its data appear on the right and its orbit is highlighted.",distanceScale:"Compare both views: space is mostly empty!"},preset:{day:"1 day/s",week:"1 week/s",month:"1 month/s",year:"1 year/s"},scale:{compressed:"Compressed (everything fits)",true:"True distances"},planet:{sun:"Sun",mercury:"Mercury",venus:"Venus",earth:"Earth",mars:"Mars",jupiter:"Jupiter",saturn:"Saturn",uranus:"Uranus",neptune:"Neptune"},measure:{daysFromStart:"Days from today",moons:"Moons",temperature:"Average temperature",dayHours:"Length of a day (Earth hours)",radius:"Radius",mass:"Mass (Earth = 1)",gravity:"Gravity on the surface",orbitalSpeed:"Orbital speed",semiMajorAxis:"Average distance (semi-major axis)",eccentricity:"Orbit stretch (eccentricity)",lightMinutes:"Sunlight travel time (minutes)",keplerRatio:"Kepler's third law check",distance:"Distance from the Sun",period:"Length of a year (Earth years)"},graph:{distance:"Distance from the Sun over time (days)"},view:{compressedScale:"Compressed distances \xB7 sizes not to scale",trueScale:"True distances \xB7 sizes not to scale",date:"{month} {day}, {year}"},challenge:{hottest:{title:"The hottest planet",description:"Find the planet with the highest average temperature.",hint:"It is not the closest one to the Sun! Look for a planet with very thick air."},moons:{title:"Moon champion",description:"Find the planet with the most moons.",hint:"It is a gas giant with beautiful rings."},weight:{title:"Heaviest step",description:"Find the planet where you would weigh the most (strongest gravity).",hint:"Compare \u201CGravity on the surface\u201D. Earth has 9.8 m/s\xB2."},trueScale:{title:"How far is far?",description:"Switch to true distances and look at the outermost planet.",hint:"Choose \u201CTrue distances\u201D and the planet Neptune."},eccentric:{title:"The most stretched orbit",description:"Find the planet whose orbit is most stretched (largest eccentricity).",hint:"Compare \u201COrbit stretch\u201D. Watch how its distance from the Sun changes during one year."}},month:{"1":"January","2":"February","3":"March","4":"April","5":"May","6":"June","7":"July","8":"August","9":"September","10":"October","11":"November","12":"December"}}},s={sim:a};export{s as default,a as sim};
